/bin/bash -lc "python - <<'PY'
mods=['openpyxl','numpy','scipy','statsmodels','sklearn','xlrd','polars']
for m in mods:
    try:
        mod=__import__(m)
        print(m, getattr(mod,'__version__','available'))
    except Exception as e:
        print(m, 'UNAVAILABLE', type(e).__name__, e)
PY"

